#!/usr/bin/env bash
# gemini-wrap.sh — run a canonical (Claude-dialect) hook under Gemini CLI.
#
# Usage, from an extension's hooks/hooks.json (generated by
# scripts/build-gemini-hooks.sh — never written by hand):
#   bash "${extensionPath}/hooks/gemini-wrap.sh" "${extensionPath}/hooks/<hook>.sh" [args...]
#   bash "${extensionPath}/hooks/gemini-wrap.sh" "${extensionPath}/hooks/<hook>.py" [args...]
#
# WHY A WRAPPER
#   Every guard in hooks/ reads a Claude-shaped payload (tool_name Edit/Write/
#   Bash, tool_input.file_path/.command) and answers in the Claude/Cursor dialect
#   of hooks/lib/hook-output.sh. Gemini names the same tools write_file/replace/
#   run_shell_command and wants {"decision":"deny","reason":...} back. Teaching
#   each guard a third dialect would put a Gemini branch in every output path of
#   every hook; this wrapper does the translation once, outside them, so the
#   hooks that run on Gemini are the identical bytes that run on Claude Code.
#
# WHAT IT DOES
#   1. Reads the Gemini payload and rewrites it to Claude's shape
#      (hooks/lib/gemini-output.sh: gemini_translate_input).
#   2. Runs the hook on that payload, with CLAUDE_PLUGIN_ROOT set to the
#      extension root for any hook that resolves a sibling through it.
#   3. Rewrites the hook's stdout into Gemini's envelope (gemini_translate_output),
#      forwards the hook's stderr unchanged, and prints EXACTLY ONE JSON object.
#   4. Always exits 0. Gemini treats every non-zero exit except 1 as a deny; a
#      canonical hook's exit 2 is a block (translated to decision:deny with its
#      stderr as the reason) and any other non-zero exit is a non-blocking error
#      on Claude (translated to {} with stderr forwarded), so the decision stays
#      the one the hook meant rather than the one Gemini's exit table implies.
#
# WHAT IT DOES NOT DO
#   It does not install, enable or trust anything; it does not read a token; it
#   runs no process other than the one hook it was given. Without jq (the
#   canonical hooks need it too) a BeforeTool call is denied with a reason and
#   every other event is allowed, so the guard layer fails closed on the one
#   event where silence would mean "allowed".
set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib/gemini-output.sh
source "${SCRIPT_DIR}/lib/gemini-output.sh"

if [[ $# -lt 1 || "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then
  sed -n '2,8p' "$0" | sed 's/^#[[:space:]]\{0,1\}//' >&2
  printf '{}\n'
  exit 0
fi

hook="$1"; shift
payload="$(gemini_read_stdin)"

# Without jq nothing below can run. Fail closed where silence would allow a
# write, open everywhere else (an advisory event has nothing to protect).
if ! command -v jq >/dev/null 2>&1; then
  ev="$(printf '%s' "$payload" | sed -n 's/.*"hook_event_name"[[:space:]]*:[[:space:]]*"\([A-Za-z]*\)".*/\1/p' | head -1)"
  if [[ "$ev" == "BeforeTool" ]]; then
    printf '{"decision":"deny","reason":"tamirs-superpowers guard cannot run: jq is not installed, so the hook payload cannot be read. Refusing to assume the call is safe."}\n'
  else
    printf '{}\n'
  fi
  exit 0
fi

if [[ ! -f "$hook" ]]; then
  printf 'gemini-wrap: hook not found: %s\n' "$hook" >&2
  printf '{}\n'
  exit 0
fi

event="$(printf '%s' "$payload" | jq -r '.hook_event_name // empty' 2>/dev/null)"
claude_payload="$(gemini_translate_input "$payload")"

# The extension root is the parent of hooks/. CLAUDE_PLUGIN_ROOT is what the
# canonical hooks.json commands are written against; nothing under hooks/
# reads it today (each script resolves its lib/ through its own path), but a
# hook that ever does must find the same answer here as on Claude Code.
export CLAUDE_PLUGIN_ROOT="${CLAUDE_PLUGIN_ROOT:-$(cd "$SCRIPT_DIR/.." && pwd)}"

case "$hook" in
  *.py) interp=(python3) ;;
  *)    interp=(bash) ;;
esac

errf="$(mktemp)"
trap 'rm -f "$errf"' EXIT
out="$(printf '%s' "$claude_payload" | "${interp[@]}" "$hook" "$@" 2>"$errf")"
rc=$?
err="$(cat "$errf" 2>/dev/null)"

case "$rc" in
  0)
    if [[ -n "${out//[[:space:]]/}" ]] && ! printf '%s' "$out" | jq -e 'type == "object"' >/dev/null 2>&1; then
      # Plain text on stdout would break Gemini's parse and turn into an allow
      # with the text as a systemMessage; say it on stderr instead and keep the
      # JSON contract.
      printf '%s\n' "$out" >&2
      out=""
    fi
    [[ -n "$err" ]] && printf '%s\n' "$err" >&2
    gemini_translate_output "$event" "$out"
    ;;
  2)
    # Claude: exit 2 blocks with stderr as the reason. Encode it so the answer
    # does not depend on Gemini's own exit-code table.
    reason="${err:-${out:-Blocked by a tamirs-superpowers hook (exit 2).}}"
    jq -cn --arg reason "$reason" '{decision:"deny", reason:$reason}'
    ;;
  *)
    # Claude: a non-blocking error, shown to the user. On Gemini the same exit
    # would be a deny, so the exit is swallowed and the text forwarded.
    printf 'gemini-wrap: %s exited %s (non-blocking)\n' "$(basename "$hook")" "$rc" >&2
    [[ -n "$err" ]] && printf '%s\n' "$err" >&2
    [[ -n "$out" ]] && printf '%s\n' "$out" >&2
    printf '{}\n'
    ;;
esac
exit 0
